
const VOCAB=[{"id":"1.1","domainId":"d1","domainName":"01. Architecture (27%)","moduleNum":"1.1","moduleTitle":"Agentic Loops","term":"Autonomous Execution Loop","phonetic":"/ɔːˈtɒn.ə.məs ˌek.sɪˈkjuː.ʃən luːp/","ptTranslation":"Ciclo de Execução Autônomo","definition":"A controlled control-flow loop where the model receives tool execution outputs and iteratively decides the next action until completing a task.","example":"The agentic loop continues executing bash commands until all unit tests pass or the max_iterations safeguard triggers.","keyContext":"Exams test how loop state is passed and how stop conditions prevent infinite execution loops."},{"id":"1.2","domainId":"d1","domainName":"01. Architecture (27%)","moduleNum":"1.2","moduleTitle":"Multi-Agent Orchestration","term":"Orchestration Topologies","phonetic":"/ˌɔː.kɪˈstreɪ.ʃən tɒˈpɒl.ə.dʒiz/","ptTranslation":"Topologias de Orquestração","definition":"Architectural patterns defining how task delegation occurs—either centralized by an orchestrator/router or decentralized across peer agents.","example":"A Router architecture evaluates incoming requests and forwards them to specialized domain agents.","keyContext":"Understanding when to use central routing versus peer handoffs."},{"id":"1.3","domainId":"d1","domainName":"01. Architecture (27%)","moduleNum":"1.3","moduleTitle":"Subagent Invocation","term":"Subagent Context Isolation","phonetic":"/ˈsʌb.eɪ.dʒənt ˈkɒn.tekst ˌaɪ.səˈleɪ.ʃən/","ptTranslation":"Isolamento de Contexto de Subagente","definition":"Spawning subagents with scoped, minimal prompt histories to prevent token bloat and context contamination.","example":"By delegating code linting to an isolated subagent, the parent orchestrator avoids consuming 30,000 tokens of raw file logs.","keyContext":"Subagents should receive only explicit inputs and return summarized outputs."},{"id":"1.4","domainId":"d1","domainName":"01. Architecture (27%)","moduleNum":"1.4","moduleTitle":"Workflow Enforcement","term":"Handoff State Payload","phonetic":"/ˈhænd.ɒf steɪt ˈpeɪ.ləʊd/","ptTranslation":"Carga Útil de Estado de Transição","definition":"Structured state transferred sequentially from one specialized agent to another during workflow transitions.","example":"The workflow enforcement layer validated the handoff payload before passing execution from reviewer to deployment agent.","keyContext":"Prevents loss of progress or critical metadata across state boundaries."},{"id":"1.5","domainId":"d1","domainName":"01. Architecture (27%)","moduleNum":"1.5","moduleTitle":"Agent SDK Hooks","term":"Event Hooks (Pre/Post Hooks)","phonetic":"/ɪˈvent hʊks/","ptTranslation":"Ganchos de Evento de Ciclo de Vida","definition":"Programmatic interceptors triggered before or after tool invocations or API requests to enforce policy or transform data.","example":"A pre-tool-call hook intercepts SQL write operations to enforce safety checks.","keyContext":"Used for auditing, authorization, and modifying input/output payloads in the Agent SDK."},{"id":"1.6","domainId":"d1","domainName":"01. Architecture (27%)","moduleNum":"1.6","moduleTitle":"Task Decomposition","term":"Attention Dilution","phonetic":"/əˈten.ʃən daɪˈluː.ʃən/","ptTranslation":"Diluição de Atenção","definition":"Degradation in accuracy that occurs when an agent attempts to execute too many complex steps or process vast files in a single pass.","example":"Breaking the refactoring plan into 5 discrete sub-tasks mitigated severe attention dilution.","keyContext":"Crucial exam trap: Shallow decomposition causes degraded output on later steps."},{"id":"1.7","domainId":"d1","domainName":"01. Architecture (27%)","moduleNum":"1.7","moduleTitle":"Session State & Resumption","term":"Checkpoint Resumption State","phonetic":"/ˈtʃek.pɔɪnt rɪˈzʌmp.ʃən steɪt/","ptTranslation":"Estado de Retomada por Ponto de Controle","definition":"Persisting intermediate conversation state and tool call results to allow long-running agent workflows to recover from network crashes.","example":"The session state layer saved a checkpoint after each step, enabling instant resumption without re-running past tools.","keyContext":"Ensures durability and fault tolerance in multi-turn server environments."},{"id":"2.1","domainId":"d2","domainName":"02. Tools & MCP (18%)","moduleNum":"2.1","moduleTitle":"Tool Interface Design","term":"Tool Schema Parameter Strictness","phonetic":"/tuːl ˈskiː.mə pəˈræm.ɪ.tər strɪkt.nəs/","ptTranslation":"Rigor nos Parâmetros do Esquema","definition":"Designing explicit JSON Schemas with descriptive parameter descriptions and precise types to eliminate ambiguous tool calls.","example":"Adding clear enum constraints to the tool schema reduced invalid arguments by 95%.","keyContext":"Claude relies heavily on field description strings inside the JSON Schema to understand parameters."},{"id":"2.2","domainId":"d2","domainName":"02. Tools & MCP (18%)","moduleNum":"2.2","moduleTitle":"Structured Error Responses","term":"Informative Tool Error Payload","phonetic":"/ɪnˈfɔː.mə.tɪv tuːl ˈer.ər ˈpeɪ.ləʊd/","ptTranslation":"Payload Informativo de Erro de Ferramenta","definition":"Returning clear, actionable error messages in tool responses so Claude can self-correct arguments in the next loop.","example":"Instead of 'Error 500', the tool returned 'Invalid date format: Expected YYYY-MM-DD', allowing Claude to retry correctly.","keyContext":"Never return raw stack traces without context; explain what went wrong and how to fix it."},{"id":"2.3","domainId":"d2","domainName":"02. Tools & MCP (18%)","moduleNum":"2.3","moduleTitle":"Tool Distribution & Choice","term":"Tool Choice Configuration","phonetic":"/tuːl tʃɔɪs kənˌfɪɡ.jəˈreɪ.ʃən/","ptTranslation":"Configuração de Seleção de Ferramentas","definition":"Controlling whether Claude decides tool use automatically ('auto'), forces at least one tool call ('any'), or executes a specific tool ('tool').","example":"Setting tool_choice = { type: 'tool', name: 'extract_data' } guarantees structured output execution.","keyContext":"Used to force deterministic schema outputs or allow open model reasoning."},{"id":"2.4","domainId":"d2","domainName":"02. Tools & MCP (18%)","moduleNum":"2.4","moduleTitle":"MCP Server Integration","term":"Model Context Protocol Primitives","phonetic":"/ˈmɒd.əl ˈkɒn.tekst ˈprəʊ.tə.kɒl/","ptTranslation":"Componentes MCP (Resources, Tools, Prompts)","definition":"The core primitives of MCP: Resources (data exposure), Tools (executable actions), and Prompts (reusable templates).","example":"The database MCP server exposes table schemas as Resources and execute_query as a Tool.","keyContext":"Central focus of Domain 2: standardizing external integrations."},{"id":"2.5","domainId":"d2","domainName":"02. Tools & MCP (18%)","moduleNum":"2.5","moduleTitle":"Built-in Tools","term":"Grep vs Glob Distinction","phonetic":"/ɡrep vɜːsəs ɡlɒb dɪˈstɪŋk.ʃən/","ptTranslation":"Diferença entre Grep e Glob","definition":"Grep searches text INSIDE file contents, while Glob matches file PATHS/NAMES based on wildcards.","example":"Use Glob to find `**/*.test.ts` files, and use Grep to find occurrences of `function processPayment` inside those files.","keyContext":"Guaranteed exam question distinction! Grep = inside files; Glob = file system names."},{"id":"3.1","domainId":"d3","domainName":"03. Claude Code (20%)","moduleNum":"3.1","moduleTitle":"CLAUDE.md Hierarchy","term":"CLAUDE.md Hierarchy Rules","phonetic":"/ˈhaɪə.rɑː.ki ruːlz/","ptTranslation":"Hierarquia do Arquivo CLAUDE.md","definition":"Configuration files located at project root or subdirectories providing instructions, coding standards, and build commands.","example":"Global instructions reside in root CLAUDE.md, while package-specific rules live in nested directory CLAUDE.md files.","keyContext":"Controls project styling, linting commands, and architecture rules for Claude CLI."},{"id":"3.2","domainId":"d3","domainName":"03. Claude Code (20%)","moduleNum":"3.2","moduleTitle":"Custom Commands & Skills","term":"Custom Slash Commands","phonetic":"/ˈkʌs.təm slæʃ kəˈmɑːndz/","ptTranslation":"Comandos Slash Personalizados","definition":"Shortcut commands (e.g., /test, /review) configured to execute predefined prompts and terminal scripts.","example":"Executing /review triggers a custom slash command script that runs static analysis before prompting Claude.","keyContext":"Standardizes repetitive developer tasks inside Claude CLI."},{"id":"3.3","domainId":"d3","domainName":"03. Claude Code (20%)","moduleNum":"3.3","moduleTitle":"Permissions & Hooks","term":"Sandbox & Tool Approval Rules","phonetic":"/ˈsænd.bɒks ænd tuːl əˈpruː.vəl/","ptTranslation":"Regras de Sandbox e Aprovação","definition":"Security boundaries configured in settings to dictate which commands execute automatically versus which require human terminal confirmation.","example":"File reading is auto-approved, but bash commands running `rm -rf` trigger explicit permission prompts.","keyContext":"Prevents untrusted or hazardous command execution in local developer setups."},{"id":"3.4","domainId":"d3","domainName":"03. Claude Code (20%)","moduleNum":"3.4","moduleTitle":"Plan Mode vs Execution","term":"Plan Mode","phonetic":"/plæn məʊd/","ptTranslation":"Modo Planejamento (Sem Execução)","definition":"A mode where Claude analyzes code and formulates a step-by-step strategy without mutating local files or making tools modifications.","example":"Before performing a multi-file migration, switch to Plan Mode to review architectural impact.","keyContext":"Reduces mistakes by requiring architectural sign-off prior to writing changes."},{"id":"3.5","domainId":"d3","domainName":"03. Claude Code (20%)","moduleNum":"3.5","moduleTitle":"Iterative Refinement","term":"Iterative Feedback Loop","phonetic":"/ɪˈtər.ə.tɪv ˈfiːd.bæk luːp/","ptTranslation":"Ciclo de Refinamento Iterativo","definition":"Refining code implementations through incremental test runs, reading error diagnostics, and applying targeted edits.","example":"Claude ran the test suite, read the failure output, edited line 42, and re-verified iteratively.","keyContext":"Focuses on minimal diff edits using targeted tools rather than rewriting entire files."},{"id":"3.6","domainId":"d3","domainName":"03. Claude Code (20%)","moduleNum":"3.6","moduleTitle":"CI/CD Pipeline Integration","term":"Headless CLI Execution","phonetic":"/ˈhed.ləs ˌiː.sī-el-ˈaɪ/","ptTranslation":"Execução CLI Headless Não Interativa","definition":"Running Claude Code inside automated pipeline environments (like GitHub Actions) using programmatic flags and environment keys.","example":"In CI/CD, Claude executes in non-interactive mode to review pull request diffs automatically.","keyContext":"Requires headless flag setup, mock inputs, and strict output handling."},{"id":"4.1","domainId":"d4","domainName":"04. Prompts & Output (20%)","moduleNum":"4.1","moduleTitle":"System Prompts","term":"Categorical Explicit Criteria","phonetic":"/ˌkæt.əˈɡɒr.ɪ.kəl ɪkˈsplɪs.ɪt kraɪˈtɪə.ri.ə/","ptTranslation":"Critérios Categóricos Explícitos","definition":"Providing precise rules and edge-case boundaries in system prompts instead of vague instructions like 'be conservative'.","example":"Replacing 'report severe bugs' with explicit criteria specifying exactly what error codes to flag dramatically reduced false positives.","keyContext":"Exam Trap: Vague words like 'be careful' fail. Categorical explicit criteria are the correct answer."},{"id":"4.2","domainId":"d4","domainName":"04. Prompts & Output (20%)","moduleNum":"4.2","moduleTitle":"Few-Shot Prompting","term":"Few-Shot Exemplars","phonetic":"/fjuː-ʃɒt ɪɡˈzem.plɑːz/","ptTranslation":"Exemplares Demonstrativos Few-Shot","definition":"Including high-quality input-output pairs inside the prompt to guide output structure, tone, and reasoning style.","example":"Providing three few-shot exemplars with complex XML formats eliminated syntax parsing errors.","keyContext":"The most effective method for teaching non-standard formatting without extra fine-tuning."},{"id":"4.3","domainId":"d4","domainName":"04. Prompts & Output (20%)","moduleNum":"4.3","moduleTitle":"Structured Output","term":"Forced Tool Structured Extraction","phonetic":"/fɔːst tuːl ˈstrʌk.tʃəd/","ptTranslation":"Extração Estruturada via Ferramentas","definition":"Utilizing tool calling mechanisms to force Claude to output strictly typed JSON objects matching a JSON schema.","example":"To guarantee JSON response schema compliance, we wrapped our extraction format as a dummy tool definition.","keyContext":"Stronger than asking for JSON in raw text prompts; avoids markdown wrapping issues."},{"id":"4.4","domainId":"d4","domainName":"04. Prompts & Output (20%)","moduleNum":"4.4","moduleTitle":"Validation & Retry Loops","term":"Validation Feedback Reflection","phonetic":"/ˌvæl.ɪˈdeɪ.ʃən ˈfiːd.bæk/","ptTranslation":"Reflexão por Feedback de Validação","definition":"Feeding system validation failures back into the model prompt to allow self-correction on subsequent tries.","example":"When schema validation failed, the exact Pydantic error message was injected into the follow-up user prompt.","keyContext":"Prevents system crashes by letting the model fix its syntax errors dynamically."},{"id":"4.5","domainId":"d4","domainName":"04. Prompts & Output (20%)","moduleNum":"4.5","moduleTitle":"Batch Processing","term":"Message Batching Optimization","phonetic":"/ˈmes.ɪdʒ ˈbætʃ.ɪŋ/","ptTranslation":"Processamento em Lote (Message Batches)","definition":"Submitting large groups of non-urgent API prompts via Anthropic's Message Batches API for 50% lower cost.","example":"Nightly documentation processing was migrated to the Message Batches API to reduce costs.","keyContext":"Asynchronous background processing with 24-hour turnaround window."},{"id":"4.6","domainId":"d4","domainName":"04. Prompts & Output (20%)","moduleNum":"4.6","moduleTitle":"Multi-Pass Review","term":"Multi-Pass Verification Pattern","phonetic":"/ˈmʌl.ti-pɑːs ˌver.ɪ.fɪˈkeɪ.ʃən/","ptTranslation":"Padrão de Verificação Multipasso","definition":"Using separate LLM calls—one to draft responses and a second, independent call to review/verify for errors.","example":"A multi-pass review pattern caught hallucinated import paths before writing changes to disk.","keyContext":"Significantly boosts accuracy on high-stakes code generation or medical compliance tasks."},{"id":"5.1","domainId":"d5","domainName":"05. Context & Reliability (15%)","moduleNum":"5.1","moduleTitle":"Context Window Management","term":"Dynamic Context Truncation","phonetic":"/daɪˈnæm.ɪk ˈkɒn.tekst trʌŋˈkeɪ.ʃən/","ptTranslation":"Truncamento Dinâmico de Contexto","definition":"Pruning old conversational history or summarizing intermediate tool logs to maintain performance within token limits.","example":"To prevent context bloat, older chat messages were condensed into a key-facts summary.","keyContext":"Prevents latency spikes and maintains attention on fresh prompt tokens."},{"id":"5.2","domainId":"d5","domainName":"05. Context & Reliability (15%)","moduleNum":"5.2","moduleTitle":"Ambiguity Resolution","term":"Ambiguity Escalation Route","phonetic":"/ˌæm.bɪˈɡjuː.ə.ti ˌes.kəˈleɪ.ʃən/","ptTranslation":"Rota de Escalabilidade por Ambiguidade","definition":"System design pattern where the model explicitly pauses execution to request user clarification when input specifications conflict.","example":"When conflicting system configs were detected, the agent escalated the issue to human review rather than guessing.","keyContext":"Prevents destructive automated execution under uncertain conditions."},{"id":"5.3","domainId":"d5","domainName":"05. Context & Reliability (15%)","moduleNum":"5.3","moduleTitle":"Error Propagation","term":"Error Cascading","phonetic":"/ˈer.ər kæsˈkeɪ.dɪŋ/","ptTranslation":"Efeito Cascata de Erro em Agentes","definition":"The risk of a single false assumption or hallucination in early agents propagating and compounding across downstream agents.","example":"Unchecked hallucinated data in Agent A caused Agents B and C to fail down the line.","keyContext":"Requires strict validation gates between agent steps to arrest faulty states."},{"id":"5.4","domainId":"d5","domainName":"05. Context & Reliability (15%)","moduleNum":"5.4","moduleTitle":"Codebase Exploration","term":"Context Degradation in Exploration","phonetic":"/ˈkɒn.tekst ˌdeɡ.rəˈdeɪ.ʃən/","ptTranslation":"Degradação de Contexto por Leitura","definition":"Loss of recall efficiency caused by dumping thousands of unneeded lines of code into the active context window.","example":"Using targeted Grep searches instead of dumping whole directories prevented severe context degradation.","keyContext":"Always read targeted files rather than bulk reading the whole codebase."},{"id":"5.5","domainId":"d5","domainName":"05. Context & Reliability (15%)","moduleNum":"5.5","moduleTitle":"Confidence Calibration","term":"Confidence Calibration & Stratified Sampling","phonetic":"/ˈkɒn.fɪ.dəns ˌkæl.ɪˈbreɪ.ʃən/","ptTranslation":"Calibração de Confiança e Amostragem","definition":"Validating model confidence metrics against labeled ground-truth datasets broken down by category, not just overall average accuracy.","example":"Aggregate metrics masked poor extraction on scanned PDFs; stratified sampling revealed the issue.","keyContext":"Exam core concept: Never judge reliability by aggregate accuracy alone; break down by document type."},{"id":"5.6","domainId":"d5","domainName":"05. Context & Reliability (15%)","moduleNum":"5.6","moduleTitle":"Information Provenance","term":"Source Provenance Attribution","phonetic":"/sɔːs ˈprɒv.ən.əns/","ptTranslation":"Atribuição de Proveniência de Fontes","definition":"Tracking and citing exact original source context IDs when synthesizing answers across multiple documentation files.","example":"The model appended source provenance metadata to every extracted requirement paragraph.","keyContext":"Crucial for auditability in enterprise search and RAG architectures."}];
const PATTERNS=[{"en":"Which approach would most effectively…?","pt":"Qual abordagem seria mais eficaz para…?","signal":"most effectively","note":"superlativo: a pergunta busca a abordagem que melhor atende ao objetivo."},{"en":"Which of the following…?","pt":"Qual das seguintes opções…?","signal":"of the following","note":"introduz alternativas; procure o verbo principal depois do bloco."},{"en":"What is the most appropriate…?","pt":"Qual é o mais apropriado…?","signal":"most appropriate","note":"most appropriate = mais apropriado; exige comparar adequação ao contexto."},{"en":"How can you ensure…?","pt":"Como você pode garantir…?","signal":"ensure","note":"ensure = garantir; normalmente aponta para uma condição ou mecanismo de confiabilidade."},{"en":"What should the system do when…?","pt":"O que o sistema deve fazer quando…?","signal":"should ... when","note":"should indica a ação esperada; when introduz a condição."},{"en":"Under which conditions…?","pt":"Sob quais condições…?","signal":"under which conditions","note":"procure as condições que limitam quando uma estratégia é válida."},{"en":"in order to","pt":"a fim de / para","signal":"in order to","note":"introduz finalidade: ação + objetivo."},{"en":"rather than","pt":"em vez de / ao invés de","signal":"rather than","note":"compara duas alternativas e indica preferência pela primeira."},{"en":"instead of","pt":"em vez de","signal":"instead of","note":"substituição: uma ação/opção ocupa o lugar de outra."},{"en":"while maintaining","pt":"mantendo enquanto / sem perder","signal":"while maintaining","note":"duas condições coexistem; atenção ao requisito que precisa continuar verdadeiro."},{"en":"without requiring","pt":"sem exigir","signal":"without requiring","note":"indica que o resultado deve ocorrer sem uma dependência adicional."},{"en":"most likely to","pt":"mais propenso a / mais provável de","signal":"most likely to","note":"expressa maior probabilidade entre alternativas; não significa certeza."},{"en":"must","pt":"deve / é obrigatório","signal":"must","note":"modal forte: obrigação ou requisito."},{"en":"may","pt":"pode / é possível","signal":"may","note":"modal de possibilidade ou permissão, dependendo do contexto."},{"en":"unless","pt":"a menos que","signal":"unless","note":"introduz exceção/condição negativa; equivale a 'except if' em muitos contextos."},{"en":"whereas","pt":"enquanto que / ao passo que","signal":"whereas","note":"contrasta duas situações ou características."}];
const QUESTIONS=[{"id":"q1","type":"content","title":"Grep vs Glob","question":"A developer needs to search a codebase to find all files that call a specific function named 'processOrder()', and then find all test files matching the naming pattern '*.test.tsx'. Which built-in tools should be used for each action?","options":["Grep for the function calls; Glob for the filename pattern.","Glob for the function calls; Grep for the filename pattern.","Use Glob for both actions.","Use Grep for both actions."],"answer":0,"explanation":"A questão contrasta conteúdo dentro dos arquivos com nomes/caminhos que seguem um padrão. No material do app, Grep é associado à busca textual e Glob à localização por padrão."},{"id":"q2","type":"content","title":"Prompt precision","question":"An engineer wants to reduce false positives in a code auditing prompt. Which system prompt modification provides the most reliable precision improvement?","options":["Add explicit categorical criteria describing what must be flagged and ignored.","Tell the model to 'be careful'.","Increase the number of adjectives in the prompt.","Remove all constraints and let the model decide freely."],"answer":0,"explanation":"O material do estudo destaca critérios explícitos e categóricos como mecanismo para definir exatamente o que deve ser sinalizado e ignorado."},{"id":"q3","type":"content","title":"Aggregate accuracy","question":"A team measures overall extraction accuracy at 94% across all processed invoices and considers automating all extractions above a 90% confidence score. What critical issue does this approach overlook?","options":["Overall accuracy can hide poor performance in specific categories or fields.","A 94% aggregate score proves every subgroup is reliable.","Confidence scores make segmentation unnecessary.","Invoice extraction never benefits from calibration."],"answer":0,"explanation":"A média geral pode esconder falhas concentradas em segmentos específicos; o material chama atenção para análise e calibração por segmento."},{"id":"q4","type":"content","title":"Context isolation","question":"A parent orchestrator delegates analysis of a very large raw log to a specialized subagent. What design most directly limits context bloat in the parent?","options":["Give the subagent scoped input and return only the summarized result needed by the parent.","Copy the entire raw log into every parent turn.","Ask every subagent to repeat the complete log in its response.","Disable all summarization and preserve every intermediate token."],"answer":0,"explanation":"O material de arquitetura usa isolamento de contexto de subagente: entradas mínimas e retorno resumido reduzem crescimento desnecessário da janela do orquestrador."},{"id":"q5","type":"content","title":"Checkpoint resumption","question":"A long-running agent workflow must recover after a network crash without rerunning completed tool calls. Which concept from the study vocabulary is directly relevant?","options":["Checkpoint Resumption State","Orchestration Topologies","Attention Dilution","Grep vs Glob"],"answer":0,"explanation":"Checkpoint Resumption State trata da persistência de estado intermediário e resultados de chamadas de ferramentas para permitir retomada."},{"id":"q6","type":"content","title":"Tool errors","question":"A tool fails and should help the model recover instead of simply returning a generic failure message. Which vocabulary item is most relevant?","options":["Informative Tool Error Payload","Attention Dilution","Context Truncation","Source Provenance Attribution"],"answer":0,"explanation":"Um payload de erro informativo fornece contexto útil para a próxima decisão do modelo e para recuperação da execução."},{"id":"q7","type":"content","title":"Structured output","question":"A downstream service requires a predictable machine-readable response. Which study concept most directly addresses enforcing a structured result?","options":["Forced Tool Structured Extraction","Multi-Agent Orchestration","Context Truncation","Session State & Resumption"],"answer":0,"explanation":"O vocabulário de Prompts & Output inclui Forced Tool Structured Extraction para extração estruturada por ferramenta."},{"id":"q8","type":"content","title":"Ambiguity","question":"A request has two plausible interpretations and choosing one silently could cause an incorrect action. Which concept best matches the intended response?","options":["Ambiguity Escalation Route","Error Cascading","Grep vs Glob","Batch Processing"],"answer":0,"explanation":"Ambiguity Escalation Route representa um caminho explícito para lidar com interpretações ambíguas em vez de assumir silenciosamente."}];
