const STORAGE=window.CCARStorage?.KEYS.breakdownProgress||'ccar_english_progress_v2';
const SETTINGS=window.CCARStorage?.KEYS.breakdownSettings||'ccar_english_settings_v2';
const BACKUP_META=window.CCARStorage?.KEYS.backupMeta||'ccar_global_backup_meta_v2';
const APP_ID=window.CCARStorage?.APP_ID||'CCAR-F Study';
const BACKUP_SCHEMA=window.CCARStorage?.SCHEMA_VERSION||2;
const APP_STORAGE_KEYS=window.CCARStorage?.APP_KEYS||[STORAGE,SETTINGS,'ccar_learned_status'];
let progress=loadProgress(), settings=loadSettings();
const NAV_STATE_KEY='ccar_breakdown_nav_state_v1';
let state={tab:'guide', modeIndex:0, reviewQueue:[], examIndex:0, examAnswers:{}, englishOnly:false, selectedDomain:'all', patternIndex:0, showTranslation:false, showContext:false, selectedOption:null, diagIndex:0, diagAnswers:{}};
try{const saved=sessionStorage.getItem(NAV_STATE_KEY);if(saved){Object.assign(state,JSON.parse(saved));sessionStorage.removeItem(NAV_STATE_KEY)}}catch(e){}
function openHelpFromBreakdown(id){try{sessionStorage.setItem(NAV_STATE_KEY,JSON.stringify(state))}catch(e){};const href=window.CCARHelp?.link(id,'breakdown')||('index.html?help='+encodeURIComponent(id)+'&return=breakdown');window.location.href=href}
function loadProgress(){try{return JSON.parse(localStorage.getItem(STORAGE))||{items:{},patterns:{},exam:{attempts:0,correct:0},diagnostic:null}}catch(e){return {items:{},patterns:{},exam:{attempts:0,correct:0},diagnostic:null}}}
function loadSettings(){try{return JSON.parse(localStorage.getItem(SETTINGS))||{}}catch(e){return {}}}
function save(){localStorage.setItem(STORAGE,JSON.stringify(progress));renderDashboard()}
function backupPayload(){return window.CCARStorage.collect()}
function downloadBackup(){const payload=window.CCARStorage.download();render()}
function backupSummary(payload){return window.CCARStorage.summarize(payload)}
async function importBackup(file){const text=await file.text();let payload;try{payload=JSON.parse(text)}catch(e){throw new Error('O arquivo não contém um JSON válido.')}payload=window.CCARStorage.validate(payload);const summary=backupSummary(payload);const date=payload.exportedAt?new Date(payload.exportedAt).toLocaleString('pt-BR'):'data desconhecida';const f=summary.flashcards,b=summary.breakdown;const ok=await window.AppModal.confirm({type:'warning',title:'Importar progresso completo?',message:`Backup de ${date}\n\nFlashcards: ${f.studied}/30 estudados · ${f.mastered} dominados\nBreakdown: ${b.studied} itens estudados · ${b.examAttempts} tentativas no Exam Mode\nDiagnóstico: ${b.diagnostic}\n\nO progresso atual de toda a aplicação será substituído.`,confirmText:'Importar backup',cancelText:'Cancelar'});if(!ok)return false;window.CCARStorage.restore(payload);await window.AppModal.alert({type:'success',title:'Backup completo importado',message:'O progresso da página principal e do English Breakdown foi restaurado. A página será recarregada.'});location.reload();return true}
function itemState(id){if(!progress.items[id])progress.items[id]={seen:0,correct:0,wrong:0,stage:0,interval:0,due:0,last:0};return progress.items[id]}
function patternState(i){const id='p'+i;if(!progress.patterns[id])progress.patterns[id]={seen:0,correct:0,wrong:0,due:0,interval:0};return progress.patterns[id]}
function now(){return Date.now()}
function days(n){return n*86400000}
function dueItems(){return VOCAB.filter(v=>itemState(v.id).due<=now())}
function adaptiveItems(){const due=dueItems();if(due.length)return due;const unseen=VOCAB.filter(v=>itemState(v.id).seen===0);if(unseen.length)return unseen;return [...VOCAB].sort((a,b)=>{const A=itemState(a.id),B=itemState(b.id);const ar=A.correct+A.wrong?A.correct/(A.correct+A.wrong):0;const br=B.correct+B.wrong?B.correct/(B.correct+B.wrong):0;return (ar-br)||(A.stage-B.stage)||(A.last-B.last)});}
function diagnosticScore(){if(!progress.diagnostic)return null;const r=progress.diagnostic.result;return r||null}
function readiness(){const cats={vocabulary:0,patterns:0,interpretation:0,technical:0,reading:0};const totals={vocabulary:0,patterns:0,interpretation:0,technical:0,reading:0};DIAGNOSTIC.forEach((q,i)=>{totals[q.cat]++;if(progress.diagnostic&&progress.diagnostic.answers&&progress.diagnostic.answers[i]===q.a)cats[q.cat]++});const vocab=VOCAB.filter(v=>itemState(v.id).seen).length;const vocabScore=Math.round((VOCAB.reduce((a,v)=>a+itemState(v.id).stage,0)/(VOCAB.length*5))*100);const patternAttempts=Object.values(progress.patterns||{}).reduce((a,x)=>a+x.seen,0),patternCorrect=Object.values(progress.patterns||{}).reduce((a,x)=>a+x.correct,0);const patternScore=patternAttempts?Math.round(patternCorrect/patternAttempts*100):Math.round((cats.patterns/totals.patterns)*100);const revAttempts=VOCAB.reduce((a,v)=>a+itemState(v.id).correct+itemState(v.id).wrong,0),revCorrect=VOCAB.reduce((a,v)=>a+itemState(v.id).correct,0);const interpretationScore=revAttempts?Math.round(revCorrect/revAttempts*100):Math.round(cats.interpretation/totals.interpretation*100);const exam=progress.exam.attempts?Math.round(progress.exam.correct/progress.exam.attempts*100):0;return {vocabulary:vocab?Math.max(vocabScore,Math.round(cats.vocabulary/totals.vocabulary*100)):Math.round(cats.vocabulary/totals.vocabulary*100),patterns:patternScore,interpretation:interpretationScore,technical:progress.exam.attempts?Math.round((exam+Math.round(cats.technical/totals.technical*100))/2):Math.round(cats.technical/totals.technical*100),reading:Math.round(cats.reading/totals.reading*100),englishOnly:Math.min(100,Math.round((vocabScore*0.5)+(progress.exam.attempts?exam*0.5:0))),timed:exam};}
function intervalFor(st,quality){if(quality==='again')return 0;if(quality==='good')return st.interval===0?1:st.interval<3?3:st.interval<7?7:st.interval<14?14:30;return st.interval===0?3:st.interval<7?7:st.interval<14?14:30}
function recordVocab(v,quality){const s=itemState(v.id);s.seen++;s.last=now();if(quality==='again'){s.wrong++;s.stage=Math.max(0,s.stage-1)}else{s.correct++;s.stage=Math.min(5,s.stage+(quality==='easy'?2:1))}s.interval=intervalFor(s,quality);s.due=quality==='again'?now()+days(0.02):now()+days(s.interval);save()}
function recordPattern(i,ok){const s=patternState(i);s.seen++;if(ok){s.correct++;s.interval=s.interval<1?1:s.interval<3?3:s.interval<7?7:14}else{s.wrong++;s.interval=0}s.due=now()+days(s.interval);save()}
function helpButton(id,label='Como funciona?'){return `<button type="button" class="btn help-btn" onclick="openHelpFromBreakdown('${id}')">💡 ${label}</button>`}
function esc(s){return String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function speak(text){if(!('speechSynthesis' in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.88;window.speechSynthesis.speak(u)}
function domainOptions(){const domains=[...new Map(VOCAB.map(v=>[v.domainId,v.domainName])).entries()];return [['all','Todos os domínios'],...domains]}
function renderDashboard(){const seen=VOCAB.filter(v=>itemState(v.id).seen>0).length;const mastered=VOCAB.filter(v=>itemState(v.id).stage>=4).length;const due=dueItems().length;const correct=VOCAB.reduce((a,v)=>a+itemState(v.id).correct,0);const wrong=VOCAB.reduce((a,v)=>a+itemState(v.id).wrong,0);const rate=correct+wrong?Math.round(correct/(correct+wrong)*100):0;const d=diagnosticScore();$('dashboard').innerHTML=`<div class="stat main"><div class="n">${d?d.overall+'%':'—'}</div><div class="l">diagnóstico inicial</div></div><div class="stat"><div class="n">${mastered}/${VOCAB.length}</div><div class="l">vocabulário consolidado</div></div><div class="stat"><div class="n">${due}</div><div class="l">revisões hoje</div></div><div class="stat"><div class="n">${rate}%</div><div class="l">acerto nas revisões</div></div><div class="stat"><div class="n">${progress.exam.attempts||0}</div><div class="l">tentativas no Exam Mode</div></div>`}
function renderGuide(app){app.innerHTML=`
<section class="card fade">
  <div class="title">📖 Como usar este módulo</div>
  <h2 style="margin:0 0 8px;font-size:24px">Seu objetivo neste módulo não é aprender inglês geral.</h2>
  <p class="muted" style="font-size:14px;line-height:1.75;margin:0">O objetivo é desenvolver a capacidade de <b style="color:#f8fafc">ler e interpretar inglês técnico</b> da certificação: reconhecer vocabulário, estruturas de pergunta, relações entre ideias e pistas que mudam o sentido da questão.</p>
  <div class="notice" style="margin-top:13px"><b>Importante:</b> você não precisa usar todas as áreas em toda sessão. O fluxo principal é <b>Diagnóstico → Aprender → Estruturas → Hoje → English Only → Exam Mode</b>.</div>
</section>
<section class="card">
  <div class="title">🧪 Primeiro passo</div>
  <p class="muted" style="font-size:13px;line-height:1.7;margin:0">Na primeira utilização, abra <b>Diagnóstico</b> e responda sem consultar as outras abas. Faça-o uma vez para estabelecer sua linha de base. Depois, use <b>Hoje</b> como sua fila principal: o sistema combina itens novos, revisões vencidas e dificuldades registradas para orientar o próximo estudo.</p>
</section>
<section class="grid2">
  <div class="card"><div class="title">🧭 O caminho do treinamento</div><div class="checklist">
    <div class="check"><b>1. 🧪 Diagnóstico</b><span>Descubra seu ponto de partida. Não repita para aumentar a pontuação; o objetivo é criar uma linha de base.</span></div>
    <div class="check"><b>2. 📚 Aprender</b><span>Conheça o termo, tradução, definição, exemplo e contexto de prova. Aqui o português pode ser usado como apoio.</span></div>
    <div class="check"><b>3. 🧩 Estruturas</b><span>Aprenda blocos recorrentes de perguntas, como <i>Which approach would most effectively...</i>, <i>rather than</i> e <i>without requiring</i>.</span></div>
    <div class="check"><b>4. 🎯 Hoje — treino adaptativo</b><span>Recupere o que estudou e revise o que precisa de atenção. O sistema usa seus erros e acertos para priorizar os próximos itens.</span></div>
    <div class="check"><b>5. 🇺🇸 English Only</b><span>Quando o vocabulário estiver mais familiar, retire a tradução. A meta é reconhecer a ideia sem depender da tradução palavra por palavra.</span></div>
    <div class="check"><b>6. ⏱ Exam Mode</b><span>Treine interpretação sob pressão usando questões autorais baseadas no material do app. Elas não são apresentadas como questões oficiais da certificação.</span></div>
  </div></div>
  <div class="card"><div class="title">🔁 O que acontece na aba Hoje</div>
    <div class="notice success"><b>Acertou:</b> o item pode ficar mais tempo sem aparecer.</div>
    <div class="notice danger"><b>Errou:</b> o item volta mais cedo para reforço.</div>
    <div class="notice"><b>Fácil:</b> o sistema aumenta o avanço do item.</div>
    <p class="muted" style="font-size:13px;line-height:1.7">A aba <b>Hoje</b> é a interface do <b>treino adaptativo</b> e da revisão espaçada. Você não precisa escolher manualmente todos os itens que deve revisar.</p>
  </div>
</section>
<section class="card"><div class="title">🧠 A regra mais importante</div>
  <div class="pattern-grid">
    <div class="pattern"><div class="en">1. O que a pergunta está pedindo?</div><div class="note">Antes de traduzir as alternativas, descubra qual é a tarefa da pergunta.</div></div>
    <div class="pattern"><div class="en">2. Qual é a estrutura?</div><div class="note">Reconheça blocos como <i>Which approach...</i>, <i>What should...</i> e <i>How can you ensure...</i>.</div></div>
    <div class="pattern"><div class="en">3. Existem palavras-sinal?</div><div class="note">Observe termos que indicam obrigação, possibilidade, contraste, condição, finalidade ou exclusão.</div></div>
    <div class="pattern"><div class="en">4. Qual conceito técnico está sendo testado?</div><div class="note">Conecte o inglês ao conteúdo técnico: agents, tools, MCP, prompts, context, reliability etc.</div></div>
  </div>
  <div class="notice" style="margin-top:13px"><b>Não tente traduzir tudo.</b> No começo você pode usar o português como apoio. Conforme avança, o treinamento reduz essa dependência gradualmente.</div>
</section>
<section class="grid2">
  <div class="card"><div class="title">📅 Rotina sugerida</div><div class="checklist">
    <div class="check"><b>10–15 min · Hoje</b><span>Faça as revisões que o sistema apresentar. Se aparecer algo novo, use Aprender para estudar o item.</span></div>
    <div class="check"><b>5–10 min · Estruturas</b><span>Pratique algumas estruturas de perguntas e tente explicar a função de cada bloco.</span></div>
    <div class="check"><b>5–10 min · English Only</b><span>Leia os termos e exemplos sem tradução e teste se ainda reconhece a ideia.</span></div>
    <div class="check"><b>2–5 questões · Exam Mode</b><span>Use como aplicação do conhecimento, não como substituto do estudo dos conceitos.</span></div>
  </div></div>
  <div class="card"><div class="title">📈 Como interpretar o progresso</div>
    <div class="barrow"><span>Estágio 1</span><b>Primeiro contato</b></div>
    <div class="barrow"><span>Estágio 2</span><b>Recuperação inicial</b></div>
    <div class="barrow"><span>Estágio 3</span><b>Reconhecimento contextual</b></div>
    <div class="barrow"><span>Estágio 4</span><b>Reconhecimento consolidado</b></div>
    <div class="barrow"><span>Estágio 5</span><b>Manutenção/revisão</b></div>
    <p class="muted" style="font-size:12px;line-height:1.6;margin-top:12px">Esses estágios são uma mecânica de estudo do aplicativo; não representam uma nota oficial de inglês nem uma medida padronizada de proficiência.</p>
  </div>
</section>
<section class="card"><div class="title">🗂️ Papel de cada área</div><div class="pattern-grid">
  <div class="pattern"><div class="en">🧪 Diagnóstico</div><div class="note">Cria seu ponto de partida. Faça uma vez no início.</div></div>
  <div class="pattern"><div class="en">📚 Aprender</div><div class="note">Estudo controlado de vocabulário e recuperação.</div></div>
  <div class="pattern"><div class="en">🧩 Estruturas</div><div class="note">Reconhecimento de padrões linguísticos de perguntas.</div></div>
  <div class="pattern"><div class="en">🎯 Hoje</div><div class="note">Fila principal de treino adaptativo e revisão.</div></div>
  <div class="pattern"><div class="en">🇺🇸 English Only</div><div class="note">Treino sem tradução imediata.</div></div>
  <div class="pattern"><div class="en">⏱ Exam Mode</div><div class="note">Aplicação e interpretação sob tempo.</div></div>
  <div class="pattern"><div class="en">📈 Progresso</div><div class="note">Acompanha consolidação, erros e indicadores de preparação.</div></div>
  <div class="pattern"><div class="en">💾 Backup</div><div class="note">Exporta e importa o progresso persistente da aplicação.</div></div>
</div></section>
<section class="card"><div class="title">📊 Indicadores de preparação</div>
  <p class="muted" style="font-size:13px;line-height:1.7;margin:0">A área de <b>Progresso</b> reúne indicadores como vocabulário, estruturas, interpretação, leitura, English Only e questões sob tempo. Eles mostram seu desempenho <b>dentro deste treinamento</b>; não são uma previsão de aprovação nem uma nota oficial.</p>
</section>`}

function renderDiagnostic(app){
  if(progress.diagnostic){const r=progress.diagnostic.result;const cats=r.categories;app.innerHTML=`<div class="toolbar"><div><b>🧪 Diagnóstico</b></div><div class="toolbar-right">${helpButton('diagnostico','Entender o diagnóstico')}</div></div><div class="notice success"><b>Diagnóstico concluído.</b> Este resultado é seu ponto de partida, não uma nota oficial de proficiência.</div><section class="card"><div class="title">Seu baseline</div><div class="diag-grid">${Object.entries(cats).map(([k,v])=>`<div class="stat"><div class="n">${v}%</div><div class="l">${({vocabulary:'Vocabulário',patterns:'Estruturas',interpretation:'Interpretação',technical:'Conceitos técnicos',reading:'Leitura'})[k]}</div></div>`).join('')}</div><div class="actions"><button class="btn primary" id="redoDiag">Refazer diagnóstico</button><button class="btn" id="goToday">Ir para Hoje →</button></div></section><section class="card"><div class="title">Como interpretar</div><p class="muted" style="font-size:13px;line-height:1.7">Use estes números para comparar seu desempenho com o que acontecerá depois de algumas semanas. O sistema adaptativo não usa apenas esta nota: ele também observa seus erros e acertos durante o treinamento.</p></section>`;$('redoDiag').onclick=()=>{progress.diagnostic=null;save();state.diagIndex=0;state.diagAnswers={};render()};$('goToday').onclick=()=>{state.tab='today';render()};return}
  const q=DIAGNOSTIC[state.diagIndex];const selected=state.diagAnswers[state.diagIndex];app.innerHTML=`<div class="toolbar"><div><b>🧪 Diagnóstico inicial</b></div><div class="toolbar-right">${helpButton('diagnostico','Como funciona?')}</div></div><div class="notice"><b>Antes de começar:</b> responda sem consultar o restante do aplicativo. O objetivo é medir seu ponto de partida, não acertar tudo.</div><section class="card"><div class="toolbar"><div><div class="title">Diagnóstico inicial · ${state.diagIndex+1}/${DIAGNOSTIC.length}</div><span class="pill">${({vocabulary:'Vocabulário',patterns:'Estruturas',interpretation:'Interpretação',technical:'Conceitos técnicos',reading:'Leitura'})[q.cat]}</span></div></div><div class="exam-q">${esc(q.q)}</div><div class="options">${q.o.map((o,i)=>`<button class="option diag-option ${selected===i?'selected':''}" data-diag="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div>${selected!==undefined?`<div class="actions"><button class="btn primary" id="nextDiag">${state.diagIndex<DIAGNOSTIC.length-1?'Próxima →':'Ver resultado'}</button></div>`:''}</section>`;document.querySelectorAll('[data-diag]').forEach(b=>b.onclick=()=>{state.diagAnswers[state.diagIndex]=Number(b.dataset.diag);render()});if($('nextDiag'))$('nextDiag').onclick=()=>{if(state.diagIndex<DIAGNOSTIC.length-1){state.diagIndex++;render()}else{const cats={};for(const c of ['vocabulary','patterns','interpretation','technical','reading']){const qs=DIAGNOSTIC.filter(x=>x.cat===c);cats[c]=Math.round(qs.filter((x,i)=>state.diagAnswers[DIAGNOSTIC.indexOf(x)]===x.a).length/qs.length*100)}const overall=Math.round(DIAGNOSTIC.filter((x,i)=>state.diagAnswers[i]===x.a).length/DIAGNOSTIC.length*100);progress.diagnostic={answers:{...state.diagAnswers},result:{overall,categories:cats,at:new Date().toISOString()}};save();render()}}}
function renderTabs(){const tabs=[['guide','📖 Como usar'],['diagnostic','🧪 Diagnóstico'],['learn','📚 Aprender'],['patterns','🧩 Estruturas'],['today','🎯 Hoje · Adaptativo'],['english','🇺🇸 English Only'],['exam','⏱ Exam Mode'],['progress','📈 Progresso'],['backup','💾 Backup']];$('tabs').innerHTML=tabs.map(([id,label])=>`<button class="tab ${state.tab===id?'active':''}" data-tab="${id}">${label}</button>`).join('');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;state.selectedOption=null;state.showTranslation=false;render()})}
function render(){renderDashboard();renderTabs();const app=$('app');if(state.tab==='guide')renderGuide(app);if(state.tab==='backup')renderBackup(app);if(state.tab==='diagnostic')renderDiagnostic(app);if(state.tab==='today')renderToday(app);if(state.tab==='learn')renderLearn(app);if(state.tab==='patterns')renderPatterns(app);if(state.tab==='english')renderEnglish(app);if(state.tab==='exam')renderExam(app);if(state.tab==='progress')renderProgress(app)}
function renderToday(app){const queue=adaptiveItems();const next=queue[0]||VOCAB[0];const s=itemState(next.id);app.innerHTML=`<div class="toolbar"><div><b>🎯 Hoje</b></div><div class="toolbar-right">${helpButton('adaptativo','Entender o treino adaptativo')}</div></div><div class="notice">O fluxo recomendado é <b>aprender → recuperar → revisar</b>. A revisão não é apenas releitura: você precisa tentar lembrar antes de revelar. A lógica de espaçamento é inspirada na literatura de aprendizagem de L2; os intervalos deste app são uma implementação prática, não um algoritmo cientificamente otimizado para este exame.</div><div class="grid2"><section class="card"><div class="title">Próximo item</div><h2 class="term">${esc(next.term)}</h2><div class="phonetic">${esc(next.phonetic||'')}</div><div class="translation">${esc(next.ptTranslation)}</div><div class="definition">${esc(next.definition)}</div><div class="example"><b>Example:</b> ${esc(next.example)}</div><div class="context"><b>Exam context:</b> ${esc(next.keyContext)}</div><div class="actions"><button class="btn primary" id="startReview">Começar revisão</button><button class="btn" id="listen">🔊 Ouvir</button></div></section><section class="card"><div class="title">Seu próximo passo</div><div class="checklist"><div class="check"><b>1. Leia o termo</b><span>Reconheça o conceito sem tentar decorar a frase inteira.</span></div><div class="check"><b>2. Recupere</b><span>Feche a tradução e tente explicar o termo em português.</span></div><div class="check"><b>3. Reconheça no contexto</b><span>Leia o exemplo e procure o termo em uma frase técnica.</span></div><div class="check"><b>4. Revise depois</b><span>Se acertar, o próximo intervalo aumenta; se errar, volta.</span></div></div></section></div>`;$('startReview').onclick=()=>{state.tab='learn';state.modeIndex=VOCAB.findIndex(v=>v.id===next.id);state.showTranslation=false;state.showContext=false;render()};$('listen').onclick=()=>speak(next.term+' . '+next.example)}
function filteredVocab(){return state.selectedDomain==='all'?VOCAB:VOCAB.filter(v=>v.domainId===state.selectedDomain)}
function renderLearn(app){const list=filteredVocab();if(!list.length){app.innerHTML='<div class="empty">Nenhum item neste domínio.</div>';return}const v=list[state.modeIndex%list.length];const s=itemState(v.id);app.innerHTML=`<div class="toolbar"><div><b>Aprender + recuperar</b><div class="dim" style="font-size:11px">Item ${((state.modeIndex%list.length)+1)}/${list.length} · estágio ${s.stage}/5</div></div><div class="toolbar-right">${helpButton('aprender','Como estudar')}<select id="domainSelect">${domainOptions().map(([id,n])=>`<option value="${id}" ${state.selectedDomain===id?'selected':''}>${esc(n)}</option>`).join('')}</select><button class="btn" id="listenTerm">🔊 Ouvir</button><button class="btn" id="englishToggle">${state.englishOnly?'🇺🇸 ON':'🇺🇸 English Only'}</button></div></div><div class="progressline"><div style="width:${Math.min(100,s.stage/5*100)}%"></div></div><section class="card fade"><div class="title">${esc(v.domainName)} · ${esc(v.moduleTitle)}</div><h2 class="term">${esc(v.term)}</h2><div class="phonetic">${esc(v.phonetic||'')}</div>${state.englishOnly?'':'<div class="translation">'+esc(v.ptTranslation)+'</div>'}<div class="definition">${esc(v.definition)}</div><div class="example"><b>Example:</b> ${esc(v.example)}</div>${state.showContext?`<div class="context"><b>Exam context:</b> ${esc(v.keyContext)}</div>`:''}<div class="actions"><button class="btn" id="contextBtn">${state.showContext?'Ocultar':'Mostrar'} contexto de prova</button><button class="btn" id="speakAll">🔊 Ouvir exemplo</button></div></section><section class="card dark"><div class="title">Retrieval check</div><div style="font-size:15px;line-height:1.7">Sem olhar acima: <b>o que ${esc(v.term)} significa e por que isso importa?</b></div><div class="hint">Pense primeiro. Depois use sua própria explicação para decidir se acertou.</div><div class="actions"><button class="btn again" id="again">❌ Errei / ainda não reconheço</button><button class="btn good" id="good">✓ Reconheci</button><button class="btn easy" id="easy">✓ Fácil</button></div></section>`;$('domainSelect').onchange=e=>{state.selectedDomain=e.target.value;state.modeIndex=0;render()};$('englishToggle').onclick=()=>{state.englishOnly=!state.englishOnly;render()};$('contextBtn').onclick=()=>{state.showContext=!state.showContext;render()};$('speakAll').onclick=()=>speak(v.term+' . '+v.example);$('listenTerm').onclick=()=>speak(v.term);$('again').onclick=()=>nextLearn(v,'again');$('good').onclick=()=>nextLearn(v,'good');$('easy').onclick=()=>nextLearn(v,'easy')}
function nextLearn(v,q){recordVocab(v,q);state.showContext=false;const list=filteredVocab();state.modeIndex=(state.modeIndex+1)%list.length;render()}
function renderPatterns(app){const p=PATTERNS[state.patternIndex%PATTERNS.length];const s=patternState(state.patternIndex%PATTERNS.length);app.innerHTML=`<div class="toolbar"><div><b>🧩 Estruturas de perguntas</b><div class="dim" style="font-size:11px">Treine blocos que aparecem em perguntas técnicas.</div></div><div class="toolbar-right">${helpButton('patterns','Como estudar')}<button class="btn" id="listenP">🔊 Ouvir</button></div></div><section class="card"><div class="title">Reconhecimento rápido · ${state.patternIndex+1}/${PATTERNS.length}</div><div style="font-size:21px;font-weight:800;line-height:1.45">${esc(p.en)}</div><div class="signal">SINAL: ${esc(p.signal)}</div><div class="actions"><button class="btn" id="revealP">${state.showTranslation?'Ocultar tradução':'Revelar tradução'}</button></div>${state.showTranslation?`<div class="reveal"><b style="color:var(--green2)">${esc(p.pt)}</b><div class="muted" style="margin-top:6px">${esc(p.note)}</div></div>`:''}</section><section class="card dark"><div class="title">Retrieval check</div><div style="font-size:14px;line-height:1.7">Sem olhar a tradução: você consegue explicar <b>${esc(p.signal)}</b> e dizer que tipo de pista ela dá na questão?</div><div class="actions"><button class="btn again" id="pAgain">❌ Não</button><button class="btn good" id="pGood">✓ Sim</button></div></section><section class="card"><div class="title">Mapa das estruturas</div><div class="pattern-grid">${PATTERNS.map((x,i)=>`<div class="pattern"><div class="en">${esc(x.en)}</div><div class="pt">${esc(x.pt)}</div><div class="signal">${esc(x.signal)}</div></div>`).join('')}</div></section>`;$('listenP').onclick=()=>speak(p.en);$('revealP').onclick=()=>{state.showTranslation=!state.showTranslation;render()};$('pAgain').onclick=()=>nextPattern(false);$('pGood').onclick=()=>nextPattern(true)}
function nextPattern(ok){recordPattern(state.patternIndex%PATTERNS.length,ok);state.patternIndex=(state.patternIndex+1)%PATTERNS.length;state.showTranslation=false;render()}
function renderEnglish(app){const due=VOCAB.filter(v=>itemState(v.id).stage>=2);const pool=due.length?due:VOCAB;const v=pool[state.modeIndex%pool.length];const s=itemState(v.id);app.innerHTML=`<div class="toolbar"><div><b>🇺🇸 English Only</b></div><div class="toolbar-right">${helpButton('englishOnly','Por que retirar a tradução?')}</div></div><div class="notice success"><b>English Only:</b> agora a tradução sai da tela. A meta não é traduzir tudo; é reconhecer a função das estruturas e o conceito técnico.</div><section class="card fade"><div class="title">English-only retrieval</div><h2 class="term">${esc(v.term)}</h2><div class="phonetic">${esc(v.phonetic||'')}</div><div class="definition">${esc(v.definition)}</div><div class="example"><b>Example:</b> ${esc(v.example)}</div><div class="actions"><button class="btn" id="speakE">🔊 Listen</button><button class="btn" id="contextE">Show exam context</button></div>${state.showContext?`<div class="reveal"><b>Exam context:</b> ${esc(v.keyContext)}</div>`:''}</section><section class="card dark"><div class="title">No-translation check</div><div style="font-size:14px;line-height:1.7">Which idea does <b>${esc(v.term)}</b> point to? Answer mentally in English or with a short Portuguese explanation <i>without rereading the translation</i>.</div><div class="actions"><button class="btn again" id="eAgain">❌ Still unclear</button><button class="btn good" id="eGood">✓ I recognize it</button></div></section>`;$('speakE').onclick=()=>speak(v.term+' . '+v.example);$('contextE').onclick=()=>{state.showContext=!state.showContext;render()};$('eAgain').onclick=()=>{recordVocab(v,'again');state.modeIndex=(state.modeIndex+1)%pool.length;state.showContext=false;render()};$('eGood').onclick=()=>{recordVocab(v,'good');state.modeIndex=(state.modeIndex+1)%pool.length;state.showContext=false;render()}}
function renderExam(app){const q=QUESTIONS[state.examIndex%QUESTIONS.length];const answered=Object.prototype.hasOwnProperty.call(state.examAnswers,q.id);const chosen=state.examAnswers[q.id];app.innerHTML=`<div class="toolbar"><div><b>Exam Mode</b><div class="dim" style="font-size:11px">Questões autorais baseadas no vocabulário/conceitos do material — não são questões oficiais da certificação.</div></div><div class="toolbar-right">${helpButton('exam','Como usar')}<span class="mono dim" style="font-size:11px">${state.examIndex+1}/${QUESTIONS.length}</span></div></div><section class="card"><div class="title">${esc(q.title)}</div><div class="exam-q">${esc(q.question)}</div><div class="options">${q.options.map((o,i)=>`<button class="option ${answered?(i===q.answer?'correct':(i===chosen?'wrong':'')):''}" data-opt="${i}" ${answered?'disabled':''}><b>${String.fromCharCode(65+i)}.</b> ${esc(o)}</button>`).join('')}</div>${answered?`<div class="explain"><b>${chosen===q.answer?'✓ Correto':'✗ Revise'}</b><br>${esc(q.explanation)}</div><div class="actions"><button class="btn primary" id="nextQ">Próxima questão</button></div>`:''}</section>`;document.querySelectorAll('[data-opt]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.opt);state.examAnswers[q.id]=i;progress.exam.attempts=(progress.exam.attempts||0)+1;if(i===q.answer)progress.exam.correct=(progress.exam.correct||0)+1;save();render()});if($('nextQ'))$('nextQ').onclick=()=>{state.examIndex=(state.examIndex+1)%QUESTIONS.length;render()}}
function renderBackup(app){
  let meta={};
  try{meta=JSON.parse(localStorage.getItem(BACKUP_META))||{}}catch(e){meta={}}
  const last=meta.lastExportedAt?new Date(meta.lastExportedAt).toLocaleString('pt-BR'):'';
  const lastHtml=last?'<div class="hint">Último backup exportado: '+esc(last)+'</div>':'';
  app.innerHTML=
    '<section class="card">'+
      '<div class="title">💾 Backup e sincronização</div>'+
      '<div class="notice success"><b>Seu progresso fica neste navegador.</b> Para estudar em outro computador, exporte um arquivo JSON, leve esse arquivo para o outro dispositivo e importe-o nesta mesma seção.</div>'+
      '<div class="backup-grid">'+
        '<div class="file-drop">'+
          '<div style="font-weight:800;font-size:16px">⬇️ Exportar progresso</div>'+
          '<p class="muted" style="font-size:13px;line-height:1.6">Gera um backup global da aplicação, incluindo os Flashcards da página inicial e todo o progresso do English Breakdown.</p>'+
          '<button class="btn primary" id="exportBackup">Exportar meu progresso</button>'+lastHtml+
        '</div>'+ 
        '<div class="file-drop">'+
          '<div style="font-weight:800;font-size:16px">⬆️ Importar progresso</div>'+
          '<p class="muted" style="font-size:13px;line-height:1.6">Selecione um arquivo <b>.json</b> exportado pelo aplicativo. O progresso atual será substituído após sua confirmação.</p>'+
          '<input id="backupFile" type="file" accept="application/json,.json">'+
        '</div>'+ 
      '</div>'+ 
    '</section>'+ 
    '<section class="card">'+
      '<div class="title">Como usar em outro dispositivo</div>'+ 
      '<div class="checklist">'+
        '<div class="check"><b>1. No computador atual</b><span>Abra esta aba e clique em “Exportar meu progresso”.</span></div>'+ 
        '<div class="check"><b>2. Transfira o JSON</b><span>Use OneDrive, Google Drive, pendrive, e-mail ou qualquer outro meio que você preferir.</span></div>'+ 
        '<div class="check"><b>3. No outro computador</b><span>Abra o aplicativo, entre em <b>💾 Backup</b> e selecione o arquivo JSON.</span></div>'+ 
        '<div class="check"><b>4. Confirme a importação</b><span>O aplicativo mostra um resumo do backup antes de substituir o progresso local.</span></div>'+ 
      '</div>'+ 
    '</section>'+ 
    '<section class="card dark">'+
      '<div class="title">O que fica no arquivo</div>'+ 
      '<div class="backup-code">schemaVersion · app · exportedAt · storage (progresso do aplicativo)</div>'+ 
      '<p class="muted" style="font-size:12px;line-height:1.6;margin-bottom:0">O backup é um arquivo JSON local. Ele reúne apenas dados persistentes da aplicação; estados temporários da interface não são exportados. Não é necessário criar conta nem usar servidor para sincronizar.</p>'+ 
    '</section>';
  $('exportBackup').onclick=downloadBackup;
  $('backupFile').onchange=async function(e){
    const file=e.target.files&&e.target.files[0];
    if(!file)return;
    try{await importBackup(file)}
    catch(err){window.AppModal.alert({type:'danger',title:'Erro ao importar',message:err.message||'Não foi possível importar o backup.'})}
    finally{e.target.value=''}
  };
}
function renderProgress(app){const done=VOCAB.filter(v=>itemState(v.id).stage>=4).length;const review=VOCAB.reduce((a,v)=>a+itemState(v.id).correct,0);const wrong=VOCAB.reduce((a,v)=>a+itemState(v.id).wrong,0);const examRate=progress.exam.attempts?Math.round((progress.exam.correct||0)/progress.exam.attempts*100):0;const weak=[...VOCAB].sort((a,b)=>{const A=itemState(a.id),B=itemState(b.id);const ar=A.correct+A.wrong?A.correct/(A.correct+A.wrong):0;const br=B.correct+B.wrong?B.correct/(B.correct+B.wrong):0;return ar-br||A.stage-B.stage}).slice(0,8);const r=readiness();const labels={vocabulary:'Vocabulário técnico',patterns:'Estruturas',interpretation:'Interpretação',technical:'Conceitos técnicos',reading:'Leitura',englishOnly:'English Only',timed:'Questões cronometradas'};app.innerHTML=`<section class="card"><div class="title">📈 Indicadores de preparação</div><div class="notice">Este painel mostra seu desempenho <b>dentro do treinamento</b>. Ele não prevê aprovação nem substitui um exame oficial.</div><div class="readiness">${Object.entries(r).map(([k,v])=>`<div><div class="readiness-row"><span>${labels[k]}</span><div class="progressline"><div style="width:${v}%"></div></div><b>${v}%</b></div></div>`).join('')}</div></section><div class="grid2"><section class="card"><div class="title">Domínio do vocabulário</div><div class="barrow"><span>Consolidado (estágio 4+)</span><b>${done}/${VOCAB.length}</b></div><div class="progressline"><div style="width:${done/VOCAB.length*100}%"></div></div><div style="margin-top:16px" class="barrow"><span>Acertos de revisão</span><b>${review}</b></div><div class="barrow"><span>Erros registrados</span><b>${wrong}</b></div><div class="barrow"><span>Acerto no Exam Mode</span><b>${examRate}%</b></div></section><section class="card"><div class="title">📌 Próximo foco</div><div class="focus-list">${weak.slice(0,4).map(v=>{const s=itemState(v.id);const total=s.correct+s.wrong;const rate=total?Math.round(s.correct/total*100):0;return `<div class="focus-item"><b>${esc(v.term)}</b><div class="dim" style="font-size:11px;margin-top:3px">${esc(v.moduleTitle)} · ${s.wrong} erro(s) · ${rate}% de acerto</div></div>`}).join('')}</div></section></div><section class="card"><div class="title">🎯 Treino adaptativo</div><p class="muted" style="font-size:13px;line-height:1.7">A aba <b>Hoje</b> prioriza primeiro itens vencidos para revisão, depois itens ainda não estudados e, quando não há revisão pendente, itens com menor desempenho e menor estágio. Assim, o conteúdo que você mais erra tende a reaparecer mais.</p><div class="actions"><button class="btn" id="resetProgress">Resetar progresso</button></div></section>`;$('resetProgress').onclick=()=>{window.AppModal.confirm({type:'danger',title:'Apagar todo o progresso?',message:'Isso apagará o progresso desta trilha, incluindo o diagnóstico e as revisões. Esta ação não pode ser desfeita.',confirmText:'Apagar progresso',cancelText:'Cancelar'}).then(ok=>{if(!ok)return;localStorage.removeItem(STORAGE);progress=loadProgress();state.diagIndex=0;state.diagAnswers={};render()})}}
function $(id){return document.getElementById(id)}
